    _openapi_values = Dict{Symbol,Any}()
    _openapi_values[:offset] = offset
    _openapi_values[:size] = size
    _openapi_values[:accession] = accession
    _openapi_values[:reviewed] = reviewed
    _openapi_values[:isoform] = isoform
    _openapi_values[:goterms] = goterms
    _openapi_values[:keywords] = keywords
    _openapi_values[:ec] = ec
    _openapi_values[:gene] = gene
    _openapi_values[:exact_gene] = exact_gene
    _openapi_values[:protein] = protein
    _openapi_values[:organism] = organism
    _openapi_values[:taxid] = taxid
    _openapi_values[:pubmed] = pubmed
    _openapi_values[:seqlength] = seqlength
    _openapi_values[:md5] = md5
    return _request(client, _OP_search_2, _openapi_values; body = ABSENT, content_type, accept, with_http_info, request_headers, request_options, stream_to)
end

