    _openapi_values[:offset] = offset
    _openapi_values[:size] = size
    _openapi_values[:sourcetype] = sourcetype
    _openapi_values[:consequencetype] = consequencetype
    _openapi_values[:wildtype] = wildtype
    _openapi_values[:alternativesequence] = alternativesequence
    _openapi_values[:location] = location
    return _request(client, _OP_searchbyhgvs, _openapi_values; body = ABSENT, content_type, accept, with_http_info, request_headers, request_options, stream_to)
end

